const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const db = require('../database/db');
const { normalizeEmail } = require('../utils/validators');

// POST /auth/login
exports.login = (req, res) => {
  const { password } = req.body;
  const email = normalizeEmail(req.body.email);

  if (!email || !password) {
    return res.status(400).json({
      error: 'Email e password são obrigatórios'
    });
  }

  db.get(
    `SELECT * FROM users WHERE lower(email) = ?`,
    [email],
    async (err, user) => {
      if (err) return res.status(500).json({ error: err.message });
      if (!user) {
        return res.status(401).json({ error: 'Email ou senha inválidos' });
      }

      if (!process.env.JWT_SECRET) {
        console.error('JWT_SECRET não definido no .env');
        return res.status(500).json({
          error: 'Servidor sem JWT_SECRET configurado. Veja o .env.example.'
        });
      }

      try {
        const isValid = await bcrypt.compare(password, user.password);
        if (!isValid) {
          return res.status(401).json({ error: 'Email ou senha inválidos' });
        }

        const token = jwt.sign(
          { id: user.id, email: user.email },
          process.env.JWT_SECRET,
          { expiresIn: process.env.JWT_EXPIRES_IN || '7d' }
        );

        res.json({
          token,
          user: {
            id: user.id,
            name: user.name,
            email: user.email
          }
        });
      } catch (e) {
        res.status(500).json({ error: e.message });
      }
    }
  );
};

const db = require('../database/db');
const dbAsync = require('../utils/dbAsync');
const { HttpError, handleError } = require('../utils/validators');

// POST /categories
exports.create = (req, res) => {
  const { name, type } = req.body;

  if (!name || !type) {
    return res.status(400).json({ error: 'name e type são obrigatórios' });
  }
  if (!['income', 'expense'].includes(type)) {
    return res.status(400).json({ error: "type deve ser 'income' ou 'expense'" });
  }

  db.run(
    `INSERT INTO categories (name, type, user_id) VALUES (?, ?, ?)`,
    [name, type, req.userId],
    function (err) {
      if (err) return res.status(500).json({ error: err.message });
      res.status(201).json({
        id: this.lastID,
        name,
        type,
        user_id: req.userId
      });
    }
  );
};

// GET /categories
exports.list = (req, res) => {
  const { type } = req.query;

  let sql = `SELECT * FROM categories WHERE user_id = ?`;
  const params = [req.userId];

  if (type) {
    sql += ` AND type = ?`;
    params.push(type);
  }

  sql += ` ORDER BY name ASC`;

  db.all(sql, params, (err, rows) => {
    if (err) return res.status(500).json({ error: err.message });
    res.json(rows);
  });
};

// DELETE /categories/:id
// Categoria com lançamentos não pode ser apagada (despesas exigem
// categoria). Responde 409 com mensagem clara em vez de erro do SQLite.
exports.remove = async (req, res) => {
  try {
    const { id } = req.params;

    const cat = await dbAsync.get(
      `SELECT id FROM categories WHERE id = ? AND user_id = ?`,
      [id, req.userId]
    );
    if (!cat) throw new HttpError(404, 'Categoria não encontrada');

    const uso = await dbAsync.get(
      `SELECT
         (SELECT COUNT(*) FROM incomes  WHERE category_id = ? AND user_id = ?) +
         (SELECT COUNT(*) FROM expenses WHERE category_id = ? AND user_id = ?) AS total`,
      [id, req.userId, id, req.userId]
    );
    if (uso.total > 0) {
      throw new HttpError(
        409,
        `Categoria em uso por ${uso.total} lançamento(s). Mova ou exclua esses lançamentos antes.`
      );
    }

    await dbAsync.run(`DELETE FROM categories WHERE id = ? AND user_id = ?`, [id, req.userId]);
    res.status(204).send();
  } catch (err) {
    handleError(res, err);
  }
};

const db = require('../database/db');
const { isValidMonth } = require('../utils/validators');

/**
 * GET /dashboard
 * Retorna o resumo financeiro do usuário logado:
 * saldo, totais, gastos/receitas por categoria e evolução mensal.
 *
 * Query params opcionais:
 *   ?month=2026-07  -> filtra os totais e categorias por mês (YYYY-MM)
 */
exports.summary = (req, res) => {
  const userId = req.userId;
  const { month } = req.query;

  if (month !== undefined && !isValidMonth(month)) {
    return res.status(400).json({ error: 'month deve estar no formato AAAA-MM' });
  }

  // filtro de mês opcional (strftime('%Y-%m', date))
  const monthFilter = month ? ` AND strftime('%Y-%m', date) = ?` : '';
  const monthParams = month ? [month] : [];

  const queries = {
    totalIncomes: {
      sql: `SELECT COALESCE(SUM(amount), 0) AS total FROM incomes
            WHERE user_id = ?${monthFilter}`,
      params: [userId, ...monthParams]
    },
    totalExpenses: {
      sql: `SELECT COALESCE(SUM(amount), 0) AS total FROM expenses
            WHERE user_id = ?${monthFilter}`,
      params: [userId, ...monthParams]
    },
    expensesByCategory: {
      sql: `SELECT COALESCE(c.name, 'Sem categoria') AS category,
                   SUM(e.amount) AS total
            FROM expenses e
            LEFT JOIN categories c ON c.id = e.category_id
            WHERE e.user_id = ?${monthFilter.replace('date', 'e.date')}
            GROUP BY c.name
            ORDER BY total DESC`,
      params: [userId, ...monthParams]
    },
    incomesByCategory: {
      sql: `SELECT COALESCE(c.name, 'Sem categoria') AS category,
                   SUM(i.amount) AS total
            FROM incomes i
            LEFT JOIN categories c ON c.id = i.category_id
            WHERE i.user_id = ?${monthFilter.replace('date', 'i.date')}
            GROUP BY c.name
            ORDER BY total DESC`,
      params: [userId, ...monthParams]
    },
    monthly: {
      sql: `SELECT month, SUM(incomes) AS incomes, SUM(expenses) AS expenses
            FROM (
              SELECT strftime('%Y-%m', date) AS month, amount AS incomes, 0 AS expenses
              FROM incomes WHERE user_id = ?
              UNION ALL
              SELECT strftime('%Y-%m', date) AS month, 0 AS incomes, amount AS expenses
              FROM expenses WHERE user_id = ?
            )
            GROUP BY month
            ORDER BY month ASC`,
      params: [userId, userId]
    }
  };

  const result = {};
  const keys = Object.keys(queries);
  let pending = keys.length;
  let responded = false;

  const fail = (err) => {
    if (!responded) {
      responded = true;
      res.status(500).json({ error: err.message });
    }
  };

  keys.forEach((key) => {
    const { sql, params } = queries[key];

    if (key === 'totalIncomes' || key === 'totalExpenses') {
      db.get(sql, params, (err, row) => {
        if (err) return fail(err);
        result[key] = row.total;
        if (--pending === 0) finish();
      });
    } else {
      db.all(sql, params, (err, rows) => {
        if (err) return fail(err);
        result[key] = rows;
        if (--pending === 0) finish();
      });
    }
  });

  function finish() {
    if (responded) return;
    responded = true;
    res.json({
      balance: result.totalIncomes - result.totalExpenses,
      total_incomes: result.totalIncomes,
      total_expenses: result.totalExpenses,
      expenses_by_category: result.expensesByCategory,
      incomes_by_category: result.incomesByCategory,
      monthly: result.monthly
    });
  }
};

const dbAsync = require('../utils/dbAsync');
const {
  HttpError,
  isPositiveNumber,
  isNonNegativeNumber,
  handleError,
} = require('../utils/validators');

/** Ícones aceitos (mesmas chaves do app). */
const ICONES = ['flag', 'wallet', 'home', 'car', 'flight', 'phone', 'school', 'laptop', 'star', 'trend'];
const ICONE_PADRAO = 'flag';

function validarIcone(icon) {
  if (!ICONES.includes(icon)) {
    throw new HttpError(400, `icon deve ser um destes: ${ICONES.join(', ')}`);
  }
}

// POST /goals
exports.create = async (req, res) => {
  try {
    const { title, target_amount, current_amount, icon } = req.body;

    if (typeof title !== 'string' || !title.trim()) {
      throw new HttpError(400, 'title é obrigatório');
    }
    if (!isPositiveNumber(target_amount)) {
      throw new HttpError(400, 'target_amount deve ser um número positivo');
    }
    const atual = current_amount === undefined || current_amount === null ? 0 : current_amount;
    if (!isNonNegativeNumber(atual)) {
      throw new HttpError(400, 'current_amount deve ser um número maior ou igual a zero');
    }
    const icone = icon === undefined || icon === null ? ICONE_PADRAO : icon;
    validarIcone(icone);

    const { lastID } = await dbAsync.run(
      `INSERT INTO goals (title, target_amount, current_amount, icon, user_id)
       VALUES (?, ?, ?, ?, ?)`,
      [title.trim(), target_amount, atual, icone, req.userId]
    );

    res.status(201).json({
      id: lastID,
      title: title.trim(),
      target_amount,
      current_amount: atual,
      icon: icone,
      user_id: req.userId,
    });
  } catch (err) {
    handleError(res, err);
  }
};

// GET /goals
exports.list = async (req, res) => {
  try {
    const rows = await dbAsync.all(
      `SELECT * FROM goals WHERE user_id = ? ORDER BY created_at DESC, id DESC`,
      [req.userId]
    );
    res.json(rows);
  } catch (err) {
    handleError(res, err);
  }
};

// PATCH /goals/:id - atualiza progresso, título, valor alvo e ícone
exports.update = async (req, res) => {
  try {
    const { current_amount, title, target_amount, icon } = req.body;
    const fields = [];
    const params = [];

    if (current_amount !== undefined) {
      if (!isNonNegativeNumber(current_amount)) {
        throw new HttpError(400, 'current_amount deve ser um número maior ou igual a zero');
      }
      fields.push('current_amount = ?');
      params.push(current_amount);
    }
    if (title !== undefined) {
      if (typeof title !== 'string' || !title.trim()) {
        throw new HttpError(400, 'title não pode ser vazio');
      }
      fields.push('title = ?');
      params.push(title.trim());
    }
    if (target_amount !== undefined) {
      if (!isPositiveNumber(target_amount)) {
        throw new HttpError(400, 'target_amount deve ser um número positivo');
      }
      fields.push('target_amount = ?');
      params.push(target_amount);
    }
    if (icon !== undefined) {
      validarIcone(icon);
      fields.push('icon = ?');
      params.push(icon);
    }

    if (fields.length === 0) throw new HttpError(400, 'Nenhum campo para atualizar');

    params.push(req.params.id, req.userId);
    const { changes } = await dbAsync.run(
      `UPDATE goals SET ${fields.join(', ')} WHERE id = ? AND user_id = ?`,
      params
    );
    if (changes === 0) throw new HttpError(404, 'Meta não encontrada');

    res.json({ message: 'Meta atualizada' });
  } catch (err) {
    handleError(res, err);
  }
};

// POST /goals/:id/aportes - soma um aporte ao valor guardado.
// A soma é feita no próprio UPDATE, então dois aportes simultâneos
// não sobrescrevem um ao outro.
exports.aportar = async (req, res) => {
  try {
    const { amount } = req.body;
    if (!isPositiveNumber(amount)) {
      throw new HttpError(400, 'amount deve ser um número positivo');
    }

    const { changes } = await dbAsync.run(
      `UPDATE goals SET current_amount = COALESCE(current_amount, 0) + ?
       WHERE id = ? AND user_id = ?`,
      [amount, req.params.id, req.userId]
    );
    if (changes === 0) throw new HttpError(404, 'Meta não encontrada');

    const meta = await dbAsync.get(
      `SELECT * FROM goals WHERE id = ? AND user_id = ?`,
      [req.params.id, req.userId]
    );
    res.json(meta);
  } catch (err) {
    handleError(res, err);
  }
};

// DELETE /goals/:id
exports.remove = async (req, res) => {
  try {
    const { changes } = await dbAsync.run(
      `DELETE FROM goals WHERE id = ? AND user_id = ?`,
      [req.params.id, req.userId]
    );
    if (changes === 0) throw new HttpError(404, 'Meta não encontrada');
    res.status(204).send();
  } catch (err) {
    handleError(res, err);
  }
};

const dbAsync = require('../utils/dbAsync');
const {
  HttpError,
  isPositiveNumber,
  isValidDate,
  isValidMonth,
  assertCategory,
  handleError,
} = require('../utils/validators');
const {
  MIN_PARCELAS,
  MAX_PARCELAS,
  dividirValor,
  datasParcelas,
  novoGrupo,
} = require('../utils/parcelas');

/**
 * Fábrica dos controllers de receitas (/incomes) e despesas (/expenses).
 * As duas tabelas têm a mesma estrutura; a diferença é que a despesa
 * exige categoria e a receita aceita ficar sem.
 *
 * @param {object} cfg
 * @param {'incomes'|'expenses'} cfg.table
 * @param {'income'|'expense'} cfg.type     tipo de categoria aceito
 * @param {boolean} cfg.categoryRequired
 * @param {string} cfg.label                 "Receita" / "Despesa"
 */
module.exports = function lancamentoController({ table, type, categoryRequired, label }) {
  const notFound = `${label} não encontrada`;

  /** Valida categoria (se veio) e devolve o valor a gravar. */
  async function resolveCategory(categoryId, userId) {
    if (categoryId === undefined || categoryId === null) {
      if (categoryRequired) throw new HttpError(400, 'category_id é obrigatório');
      return null;
    }
    await assertCategory(categoryId, userId, type);
    return categoryId;
  }

  /**
   * Cria uma compra/receita parcelada: `amount` é o valor TOTAL, dividido
   * em `n` lançamentos mensais ligados pelo mesmo parcela_grupo.
   * Tudo numa transação: ou grava todas as parcelas, ou nenhuma.
   */
  async function criarParcelado(req, res, { amount, description, date, categoryId, n }) {
    const grupo = novoGrupo();
    const valores = dividirValor(amount, n);
    const datas = datasParcelas(date, n);
    const criadas = [];

    await dbAsync.run('BEGIN');
    try {
      for (let i = 0; i < n; i++) {
        const { lastID } = await dbAsync.run(
          `INSERT INTO ${table}
             (amount, description, date, category_id, parcelado, user_id,
              parcela_grupo, parcela_numero, parcela_total)
           VALUES (?, ?, ?, ?, 1, ?, ?, ?, ?)`,
          [valores[i], description || null, datas[i], categoryId, req.userId, grupo, i + 1, n]
        );
        criadas.push({ id: lastID, amount: valores[i], date: datas[i], parcela_numero: i + 1 });
      }
      await dbAsync.run('COMMIT');
    } catch (err) {
      await dbAsync.run('ROLLBACK').catch(() => {});
      throw err;
    }

    res.status(201).json({
      ...criadas[0],
      description: description || null,
      category_id: categoryId,
      parcelado: 1,
      user_id: req.userId,
      parcela_grupo: grupo,
      parcela_total: n,
      valor_total: amount,
      parcelas: criadas,
    });
  }

  // POST /
  // Campo opcional `parcelas` (2 a 48): divide `amount` em parcelas mensais.
  async function create(req, res) {
    try {
      const { amount, description, date, category_id, parcelado, parcelas } = req.body;

      if (amount === undefined || amount === null || !date) {
        throw new HttpError(400, 'amount e date são obrigatórios');
      }
      if (!isPositiveNumber(amount)) {
        throw new HttpError(400, 'amount deve ser um número positivo');
      }
      if (!isValidDate(date)) {
        throw new HttpError(400, 'date deve estar no formato AAAA-MM-DD');
      }
      if (parcelas !== undefined && parcelas !== null && parcelas !== 1) {
        if (!Number.isInteger(parcelas) || parcelas < MIN_PARCELAS || parcelas > MAX_PARCELAS) {
          throw new HttpError(
            400,
            `parcelas deve ser um número inteiro de ${MIN_PARCELAS} a ${MAX_PARCELAS}`
          );
        }
        if (amount < parcelas * 0.01) {
          throw new HttpError(400, 'amount é pequeno demais para tantas parcelas');
        }
      }
      const categoryId = await resolveCategory(category_id, req.userId);

      if (Number.isInteger(parcelas) && parcelas >= MIN_PARCELAS) {
        return await criarParcelado(req, res, {
          amount, description, date, categoryId, n: parcelas,
        });
      }

      const { lastID } = await dbAsync.run(
        `INSERT INTO ${table} (amount, description, date, category_id, parcelado, user_id)
         VALUES (?, ?, ?, ?, ?, ?)`,
        [amount, description || null, date, categoryId, parcelado ? 1 : 0, req.userId]
      );

      res.status(201).json({
        id: lastID,
        amount,
        description: description || null,
        date,
        category_id: categoryId,
        parcelado: parcelado ? 1 : 0,
        user_id: req.userId,
      });
    } catch (err) {
      handleError(res, err);
    }
  }

  // GET /   (aceita ?month=AAAA-MM)
  async function list(req, res) {
    try {
      const { month } = req.query;
      const params = [req.userId];
      let filtro = '';

      if (month !== undefined) {
        if (!isValidMonth(month)) {
          throw new HttpError(400, 'month deve estar no formato AAAA-MM');
        }
        filtro = ` AND strftime('%Y-%m', t.date) = ?`;
        params.push(month);
      }

      const rows = await dbAsync.all(
        `SELECT t.*, c.name AS category_name
         FROM ${table} t
         LEFT JOIN categories c ON c.id = t.category_id
         WHERE t.user_id = ?${filtro}
         ORDER BY t.date DESC, t.id DESC`,
        params
      );
      res.json(rows);
    } catch (err) {
      handleError(res, err);
    }
  }

  // PUT /:id
  async function update(req, res) {
    try {
      const { id } = req.params;
      const { amount, description, date, category_id, parcelado } = req.body;

      const fields = [];
      const params = [];

      if (amount !== undefined) {
        if (!isPositiveNumber(amount)) {
          throw new HttpError(400, 'amount deve ser um número positivo');
        }
        fields.push('amount = ?');
        params.push(amount);
      }
      if (description !== undefined) {
        fields.push('description = ?');
        params.push(description);
      }
      if (date !== undefined) {
        if (!isValidDate(date)) {
          throw new HttpError(400, 'date deve estar no formato AAAA-MM-DD');
        }
        fields.push('date = ?');
        params.push(date);
      }
      if (category_id !== undefined) {
        fields.push('category_id = ?');
        params.push(await resolveCategory(category_id, req.userId));
      }
      if (parcelado !== undefined) {
        fields.push('parcelado = ?');
        params.push(parcelado ? 1 : 0);
      }

      if (fields.length === 0) {
        throw new HttpError(400, 'Nenhum campo para atualizar');
      }

      params.push(id, req.userId);
      const { changes } = await dbAsync.run(
        `UPDATE ${table} SET ${fields.join(', ')} WHERE id = ? AND user_id = ?`,
        params
      );
      if (changes === 0) throw new HttpError(404, notFound);

      res.json({ message: `${label} atualizada` });
    } catch (err) {
      handleError(res, err);
    }
  }

  // DELETE /:id
  async function remove(req, res) {
    try {
      const { changes } = await dbAsync.run(
        `DELETE FROM ${table} WHERE id = ? AND user_id = ?`,
        [req.params.id, req.userId]
      );
      if (changes === 0) throw new HttpError(404, notFound);
      res.status(204).send();
    } catch (err) {
      handleError(res, err);
    }
  }

  // DELETE /grupo/:grupo - exclui todas as parcelas de uma compra/receita
  async function removeGrupo(req, res) {
    try {
      const { changes } = await dbAsync.run(
        `DELETE FROM ${table} WHERE parcela_grupo = ? AND user_id = ?`,
        [req.params.grupo, req.userId]
      );
      if (changes === 0) throw new HttpError(404, 'Parcelamento não encontrado');
      res.json({ removidas: changes });
    } catch (err) {
      handleError(res, err);
    }
  }

  return { create, list, update, remove, removeGrupo };
};

const crypto = require('crypto');
const bcrypt = require('bcrypt');
const dbAsync = require('../utils/dbAsync');
const { enviarEmail } = require('../utils/mailer');
const {
  HttpError,
  normalizeEmail,
  isValidEmail,
  handleError,
} = require('../utils/validators');

const VALIDADE_MIN = 15; // minutos que o código vale
const MAX_TENTATIVAS = 5; // erros permitidos por código
const ESPERA_REENVIO_S = 60; // intervalo mínimo entre pedidos

// Mesma resposta exista ou não a conta, para não revelar quais
// e-mails estão cadastrados.
const RESPOSTA_PEDIDO = {
  message: 'Se o e-mail estiver cadastrado, enviamos um código de 6 dígitos.',
  validade_minutos: VALIDADE_MIN,
  reenviar_em_segundos: ESPERA_REENVIO_S,
};

const ERRO_CODIGO = 'Código inválido ou expirado. Peça um novo código.';

/**
 * POST /auth/forgot-password  { email }
 * Gera um código de 6 dígitos, válido por 15 minutos, e envia por e-mail.
 */
exports.forgotPassword = async (req, res) => {
  try {
    const email = normalizeEmail(req.body.email);
    if (!isValidEmail(email)) throw new HttpError(400, 'Informe um e-mail válido');

    const user = await dbAsync.get(
      `SELECT id, name, email FROM users WHERE lower(email) = ?`,
      [email]
    );
    if (!user) return res.json(RESPOSTA_PEDIDO);

    const agora = Date.now();

    // Evita disparar vários e-mails seguidos.
    const ultimo = await dbAsync.get(
      `SELECT created_at FROM password_resets
       WHERE user_id = ? ORDER BY created_at DESC LIMIT 1`,
      [user.id]
    );
    if (ultimo && agora - ultimo.created_at < ESPERA_REENVIO_S * 1000) {
      return res.json(RESPOSTA_PEDIDO);
    }

    const codigo = String(crypto.randomInt(0, 1000000)).padStart(6, '0');
    const codeHash = await bcrypt.hash(codigo, 10);

    // Só o código mais recente vale.
    await dbAsync.run(
      `UPDATE password_resets SET used = 1 WHERE user_id = ? AND used = 0`,
      [user.id]
    );
    await dbAsync.run(
      `INSERT INTO password_resets (user_id, code_hash, expires_at, created_at)
       VALUES (?, ?, ?, ?)`,
      [user.id, codeHash, agora + VALIDADE_MIN * 60 * 1000, agora]
    );

    const primeiroNome = (user.name || '').trim().split(/\s+/)[0] || 'tudo bem';
    try {
      await enviarEmail({
        para: user.email,
        assunto: `FinUp · seu código é ${codigo}`,
        texto:
          `Olá, ${primeiroNome}!\n\n` +
          `Seu código para redefinir a senha do FinUp é: ${codigo}\n\n` +
          `Ele vale por ${VALIDADE_MIN} minutos. Se você não pediu, ignore este e-mail.`,
        html:
          `<div style="font-family:Roboto,Arial,sans-serif;color:#1E293B">` +
          `<p>Olá, ${primeiroNome}!</p>` +
          `<p>Seu código para redefinir a senha do <b>FinUp</b> é:</p>` +
          `<p style="font-size:32px;font-weight:700;letter-spacing:6px;color:#2F6FE4">${codigo}</p>` +
          `<p>Ele vale por ${VALIDADE_MIN} minutos. Se você não pediu, ignore este e-mail.</p>` +
          `</div>`,
      });
    } catch (err) {
      // Não revela ao cliente se a conta existe; o erro fica no log.
      console.error('Falha ao enviar e-mail de recuperação:', err.message);
    }

    res.json(RESPOSTA_PEDIDO);
  } catch (err) {
    handleError(res, err);
  }
};

/**
 * POST /auth/reset-password  { email, code, new_password }
 * Confere o código e troca a senha. Cada código aceita 5 tentativas.
 */
exports.resetPassword = async (req, res) => {
  try {
    const email = normalizeEmail(req.body.email);
    const code = typeof req.body.code === 'string' ? req.body.code.trim() : '';
    const novaSenha = req.body.new_password;

    if (!isValidEmail(email) || !/^\d{6}$/.test(code)) {
      throw new HttpError(400, 'Informe o e-mail e o código de 6 dígitos');
    }
    if (typeof novaSenha !== 'string' || novaSenha.length < 6) {
      throw new HttpError(400, 'A nova senha deve ter pelo menos 6 caracteres');
    }

    const user = await dbAsync.get(`SELECT id FROM users WHERE lower(email) = ?`, [email]);
    if (!user) throw new HttpError(400, ERRO_CODIGO);

    const pedido = await dbAsync.get(
      `SELECT * FROM password_resets
       WHERE user_id = ? AND used = 0
       ORDER BY created_at DESC LIMIT 1`,
      [user.id]
    );
    if (!pedido || pedido.expires_at < Date.now() || pedido.attempts >= MAX_TENTATIVAS) {
      throw new HttpError(400, ERRO_CODIGO);
    }

    const confere = await bcrypt.compare(code, pedido.code_hash);
    if (!confere) {
      await dbAsync.run(
        `UPDATE password_resets SET attempts = attempts + 1 WHERE id = ?`,
        [pedido.id]
      );
      const restantes = MAX_TENTATIVAS - pedido.attempts - 1;
      throw new HttpError(
        400,
        restantes > 0
          ? `Código incorreto. Você ainda tem ${restantes} tentativa(s).`
          : ERRO_CODIGO
      );
    }

    const hash = await bcrypt.hash(novaSenha, 10);
    await dbAsync.run(`UPDATE users SET password = ? WHERE id = ?`, [hash, user.id]);
    await dbAsync.run(`UPDATE password_resets SET used = 1 WHERE user_id = ?`, [user.id]);

    res.json({ message: 'Senha redefinida. Entre com a nova senha.' });
  } catch (err) {
    handleError(res, err);
  }
};

const bcrypt = require('bcrypt');
const db = require('../database/db');
const { normalizeEmail, isValidEmail } = require('../utils/validators');

// Categorias criadas automaticamente para cada usuário novo,
// espelhando as opções disponíveis no app Flutter.
const DEFAULT_CATEGORIES = {
  income: ['Salário', 'Freelance', 'Investimentos', 'Bônus', 'Outros'],
  expense: [
    'Alimentação', 'Transporte', 'Moradia', 'Saúde', 'Lazer',
    'Compras', 'Assinaturas', 'Impostos', 'Outros'
  ]
};

function seedDefaultCategories(userId) {
  const stmt = db.prepare(
    `INSERT INTO categories (name, type, user_id) VALUES (?, ?, ?)`
  );
  for (const [type, names] of Object.entries(DEFAULT_CATEGORIES)) {
    for (const name of names) {
      stmt.run(name, type, userId);
    }
  }
  stmt.finalize();
}

// POST /users - cadastrar novo usuário
exports.create = async (req, res) => {
  const { password } = req.body;
  const name = typeof req.body.name === 'string' ? req.body.name.trim() : req.body.name;
  const email = normalizeEmail(req.body.email);

  if (!name || !email || !password) {
    return res.status(400).json({
      error: 'Os campos name, email e password são obrigatórios'
    });
  }

  if (!isValidEmail(email)) {
    return res.status(400).json({ error: 'Email inválido' });
  }

  if (typeof password !== 'string' || password.length < 6) {
    return res.status(400).json({
      error: 'A senha deve ter pelo menos 6 caracteres'
    });
  }

  try {
    const existente = await new Promise((resolve, reject) =>
      db.get(`SELECT id FROM users WHERE lower(email) = ?`, [email],
        (err, row) => (err ? reject(err) : resolve(row)))
    );
    if (existente) {
      return res.status(409).json({ error: 'Email já cadastrado' });
    }

    const hashedPassword = await bcrypt.hash(password, 10);

    db.run(
      `INSERT INTO users (name, email, password) VALUES (?, ?, ?)`,
      [name, email, hashedPassword],
      function (err) {
        if (err) {
          if (err.message.includes('UNIQUE')) {
            return res.status(409).json({ error: 'Email já cadastrado' });
          }
          return res.status(500).json({ error: err.message });
        }

        // cria as categorias padrão do usuário
        seedDefaultCategories(this.lastID);

        res.status(201).json({
          id: this.lastID,
          name,
          email
        });
      }
    );
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
};

